BEGIN;
DO $$
DECLARE
  v_subject_id UUID;
  v_topic_id UUID;
  v_test_id BIGINT;
BEGIN
  SELECT id INTO v_subject_id FROM test_subjects WHERE name ILIKE '%cardio%' ORDER BY id LIMIT 1;
  IF v_subject_id IS NULL THEN
    INSERT INTO test_subjects (name, description) VALUES ('Cardiovascular System', 'Cardiovascular notes') RETURNING id INTO v_subject_id;
  END IF;
  SELECT id INTO v_topic_id FROM test_topics WHERE name = 'Anticoagulants' ORDER BY (SELECT COUNT(*) FROM test_questions q WHERE q.topic_id = test_topics.id) DESC, created_at ASC LIMIT 1;
  IF v_topic_id IS NULL THEN
    INSERT INTO test_topics (subject_id, name, description, status) VALUES (v_subject_id, 'Anticoagulants', 'Anticoagulant pharmacology, monitoring, antidotes, and bridge safety', 'published') RETURNING id INTO v_topic_id;
  END IF;
  SELECT id INTO v_test_id FROM tests WHERE is_active = true ORDER BY id LIMIT 1;
  IF v_test_id IS NULL THEN
    INSERT INTO tests (test_name, system_category, description, is_active)
    VALUES ('Cardiovascular System - Anticoagulants (Generated)', 'Cardiovascular System', 'Auto-generated NCLEX question set', true)
    RETURNING id INTO v_test_id;
  END IF;
  DELETE FROM test_questions WHERE topic_id = v_topic_id AND category = 'Anticoagulants - NCLEX';
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Anticoagulants note, which statement about "aPTT role" is most accurate?', 'According to the Anticoagulants note, which statement about "aPTT role" is most accurate?', '[{"id": "a", "text": "Therapeutic heparin aPTT is 45–80 sec."}, {"id": "b", "text": "Continue infusion and recheck next shift."}, {"id": "c", "text": "Therapeutic heparin aPTT is below 20 sec."}, {"id": "d", "text": "Vitamin K is the heparin antidote."}]'::jsonb, '["a"]'::jsonb, 'Correct because aPTT monitors heparin therapy; normal is about 30–40 sec and therapeutic heparin range is 45–80 sec. Trend aPTT during heparin titration to avoid under- or over-anticoagulation.', 'Anticoagulants - NCLEX', false, 1, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "PT/INR role" in Anticoagulants. Which statement is correct?', 'The nurse is reviewing "PT/INR role" in Anticoagulants. Which statement is correct?', '[{"id": "a", "text": "INR goal for most patients is below 1."}, {"id": "b", "text": "Warfarin is monitored by aPTT only."}, {"id": "c", "text": "Give antidote before any assessment."}, {"id": "d", "text": "INR is used for warfarin monitoring."}]'::jsonb, '["d"]'::jsonb, 'Correct because PT/INR monitor warfarin; INR therapeutic range is 2–3 for most indications. Use INR trends to guide safe warfarin dosing.', 'Anticoagulants - NCLEX', false, 2, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "heparin basics" in Anticoagulants?', 'Which clinical judgment is most accurate regarding "heparin basics" in Anticoagulants?', '[{"id": "a", "text": "Antidote planning is unnecessary when labs are elevated."}, {"id": "b", "text": "Heparin is chosen when rapid anticoagulation is needed."}, {"id": "c", "text": "Warfarin patients should take NSAIDs for routine pain."}, {"id": "d", "text": "Heparin requires 2–5 days to start working."}]'::jsonb, '["b"]'::jsonb, 'Correct because Heparin is given IV or SubQ, has immediate IV onset, and is used for DVT, PE, ACS, dialysis, and perioperative prevention. Heparin is chosen when rapid anticoagulation is needed.', 'Anticoagulants - NCLEX', false, 3, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "heparin antidote" in Anticoagulants?', 'In rapid prioritization, which statement is most consistent with "heparin antidote" in Anticoagulants?', '[{"id": "a", "text": "Protamine sulfate reverses heparin."}, {"id": "b", "text": "Warfarin is only used during surgery."}, {"id": "c", "text": "Medical alert ID is unnecessary."}, {"id": "d", "text": "Vitamin K is the heparin antidote."}]'::jsonb, '["a"]'::jsonb, 'Correct because Protamine sulfate is the antidote for heparin. Prepare protamine quickly when significant heparin-associated bleeding risk is present.', 'Anticoagulants - NCLEX', false, 4, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "aPTT above 80" in Anticoagulants would the nurse recognize as correct?', 'Which conclusion about "aPTT above 80" in Anticoagulants would the nurse recognize as correct?', '[{"id": "a", "text": "Overlap is unnecessary if INR is pending."}, {"id": "b", "text": "Continue infusion and recheck next shift."}, {"id": "c", "text": "Stop heparin infusion if aPTT is >80 sec."}, {"id": "d", "text": "Stop heparin the same day warfarin starts."}]'::jsonb, '["c"]'::jsonb, 'Correct because If aPTT exceeds 80 sec: stop infusion, assess vitals for bleeding, prepare protamine, then notify provider before giving antidote. Follow sequence: stop, assess, prepare, call.', 'Anticoagulants - NCLEX', false, 5, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Anticoagulants note, which statement about "HIT recognition" is most accurate?', 'According to the Anticoagulants note, which statement about "HIT recognition" is most accurate?', '[{"id": "a", "text": "Heparin should be stopped in suspected HIT."}, {"id": "b", "text": "Leafy greens must be eliminated forever."}, {"id": "c", "text": "Continue heparin despite HIT signs."}, {"id": "d", "text": "Heparin stops after one therapeutic INR."}]'::jsonb, '["a"]'::jsonb, 'Correct because HIT is suspected when platelets drop more than 50% on heparin; stop heparin and switch to argatroban. HIT increases clotting risk paradoxically despite thrombocytopenia.', 'Anticoagulants - NCLEX', false, 6, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "warfarin basics" in Anticoagulants. Which statement is correct?', 'The nurse is reviewing "warfarin basics" in Anticoagulants. Which statement is correct?', '[{"id": "a", "text": "Warfarin monitoring is discontinued once stable."}, {"id": "b", "text": "Vitamin K intake has no effect on warfarin."}, {"id": "c", "text": "Warfarin is used for long-term anticoagulation."}, {"id": "d", "text": "Warfarin is only used during surgery."}]'::jsonb, '["c"]'::jsonb, 'Correct because Warfarin is oral and has delayed onset of 2–5 days, so it is used for long-term anticoagulation. Delayed onset drives need for bridging in acute clot treatment.', 'Anticoagulants - NCLEX', false, 7, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "warfarin therapeutic range" in Anticoagulants?', 'Which clinical judgment is most accurate regarding "warfarin therapeutic range" in Anticoagulants?', '[{"id": "a", "text": "Blood pressure alone is enough for all anticoagulant safety decisions."}, {"id": "b", "text": "Antidote planning is unnecessary when labs are elevated."}, {"id": "c", "text": "Valve patients often require higher anticoagulation intensity."}, {"id": "d", "text": "Warfarin has one fixed INR for all patients."}]'::jsonb, '["c"]'::jsonb, 'Correct because Therapeutic INR is usually 2–3, but mechanical heart valves often target 2.5–3.5. Valve patients often require higher anticoagulation intensity.', 'Anticoagulants - NCLEX', false, 8, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "warfarin antidote" in Anticoagulants?', 'In rapid prioritization, which statement is most consistent with "warfarin antidote" in Anticoagulants?', '[{"id": "a", "text": "Give antidote before assessment."}, {"id": "b", "text": "Phytonadione is vitamin K name in note."}, {"id": "c", "text": "Stop heparin the same day warfarin starts."}, {"id": "d", "text": "Andexanet alfa reverses warfarin."}]'::jsonb, '["b"]'::jsonb, 'Correct because Vitamin K (phytonadione) is the reversal agent for warfarin. Know warfarin-vitamin K pair for rapid NCLEX decisions.', 'Anticoagulants - NCLEX', false, 9, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "warfarin teaching vitamin K" in Anticoagulants would the nurse recognize as correct?', 'Which conclusion about "warfarin teaching vitamin K" in Anticoagulants would the nurse recognize as correct?', '[{"id": "a", "text": "Stop heparin the same day warfarin starts."}, {"id": "b", "text": "Overlap is unnecessary if INR is pending."}, {"id": "c", "text": "Vitamin K intake has no effect on warfarin."}, {"id": "d", "text": "Diet consistency prevents INR instability."}]'::jsonb, '["d"]'::jsonb, 'Correct because Patients should keep vitamin K intake consistent rather than eliminating leafy greens entirely. Diet consistency prevents INR instability.', 'Anticoagulants - NCLEX', false, 10, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Anticoagulants note, which statement about "warfarin teaching interactions" is most accurate?', 'According to the Anticoagulants note, which statement about "warfarin teaching interactions" is most accurate?', '[{"id": "a", "text": "Antidote planning is unnecessary when labs are elevated."}, {"id": "b", "text": "Medication/food interaction review is a safety essential."}, {"id": "c", "text": "Warfarin monitoring is discontinued once stable."}, {"id": "d", "text": "Warfarin patients should take NSAIDs for routine pain."}]'::jsonb, '["b"]'::jsonb, 'Correct because Avoid NSAIDs and grapefruit while on warfarin due to increased bleeding risk or level changes. Medication/food interaction review is a safety essential.', 'Anticoagulants - NCLEX', false, 11, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "warfarin bleeding teaching" in Anticoagulants. Which statement is correct?', 'The nurse is reviewing "warfarin bleeding teaching" in Anticoagulants. Which statement is correct?', '[{"id": "a", "text": "Bleeding signs can be ignored if INR is therapeutic."}, {"id": "b", "text": "Antidote planning is unnecessary when labs are elevated."}, {"id": "c", "text": "Early bleeding recognition prevents severe complications."}, {"id": "d", "text": "Warfarin monitoring is discontinued once stable."}]'::jsonb, '["c"]'::jsonb, 'Correct because Teach patients to report unusual bleeding, hematuria, or blood in stool and wear a medical alert bracelet. Early bleeding recognition prevents severe complications.', 'Anticoagulants - NCLEX', false, 12, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "bridge overlap duration" in Anticoagulants?', 'Which clinical judgment is most accurate regarding "bridge overlap duration" in Anticoagulants?', '[{"id": "a", "text": "Heparin provides immediate effect during bridge."}, {"id": "b", "text": "Call provider before stopping active infusion."}, {"id": "c", "text": "Stop heparin the same day warfarin starts."}, {"id": "d", "text": "aPTT >80 sec suggests under-anticoagulation."}]'::jsonb, '["a"]'::jsonb, 'Correct because When transitioning heparin to warfarin, overlap both drugs for at least 5–7 days. Bridge prevents gaps in anticoagulation while warfarin effect develops.', 'Anticoagulants - NCLEX', false, 13, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "bridge discontinuation rule" in Anticoagulants?', 'In rapid prioritization, which statement is most consistent with "bridge discontinuation rule" in Anticoagulants?', '[{"id": "a", "text": "Call provider before stopping active infusion."}, {"id": "b", "text": "Therapeutic INR must persist two consecutive days."}, {"id": "c", "text": "Antidote planning is unnecessary when labs are elevated."}, {"id": "d", "text": "Heparin stops after one therapeutic INR."}]'::jsonb, '["b"]'::jsonb, 'Correct because Do not stop heparin until INR is therapeutic 2–3 for two consecutive days. Require stable therapeutic INR before removing rapid-acting anticoagulant.', 'Anticoagulants - NCLEX', false, 14, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "stable INR follow-up" in Anticoagulants would the nurse recognize as correct?', 'Which conclusion about "stable INR follow-up" in Anticoagulants would the nurse recognize as correct?', '[{"id": "a", "text": "Hematuria is expected and not concerning."}, {"id": "b", "text": "Warfarin monitoring is discontinued once stable."}, {"id": "c", "text": "Antidote planning is unnecessary when labs are elevated."}, {"id": "d", "text": "Stable warfarin INR checks can be every 3 weeks."}]'::jsonb, '["d"]'::jsonb, 'Correct because Once INR is stable, warfarin monitoring can be every 3 weeks per note. Stable outpatient monitoring still requires routine checks.', 'Anticoagulants - NCLEX', false, 15, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Anticoagulants note, which statement about "critical high-risk thresholds" is most accurate?', 'According to the Anticoagulants note, which statement about "critical high-risk thresholds" is most accurate?', '[{"id": "a", "text": "aPTT >80 sec suggests under-anticoagulation."}, {"id": "b", "text": "aPTT >80 sec is high hemorrhage risk in note."}, {"id": "c", "text": "Anticoagulants do not require routine monitoring."}, {"id": "d", "text": "Antidote planning is unnecessary when labs are elevated."}]'::jsonb, '["b"]'::jsonb, 'Correct because INR greater than 4 or aPTT greater than 80 sec indicates high hemorrhage risk and immediate intervention. Recognize threshold triggers for urgent safety response.', 'Anticoagulants - NCLEX', false, 16, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "STOP ASSESS PREPARE CALL" in Anticoagulants. Which statement is correct?', 'The nurse is reviewing "STOP ASSESS PREPARE CALL" in Anticoagulants. Which statement is correct?', '[{"id": "a", "text": "Call provider before stopping active infusion."}, {"id": "b", "text": "Enoxaparin is fully reversed by vitamin K."}, {"id": "c", "text": "Assess for low BP/high HR/pallor/bleeding."}, {"id": "d", "text": "Xa inhibitors are monitored by daily INR."}]'::jsonb, '["c"]'::jsonb, 'Correct because NCLEX priority order for suspected internal bleeding is STOP anticoagulant, ASSESS vitals/bleeding, PREPARE antidote, then CALL provider. Sequence discipline improves emergency anticoagulant safety.', 'Anticoagulants - NCLEX', false, 17, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "internal bleeding signs" in Anticoagulants?', 'Which clinical judgment is most accurate regarding "internal bleeding signs" in Anticoagulants?', '[{"id": "a", "text": "Antidote planning is unnecessary when labs are elevated."}, {"id": "b", "text": "Combine hemodynamic and symptom clues for early detection."}, {"id": "c", "text": "Blood pressure alone is enough for all anticoagulant safety decisions."}, {"id": "d", "text": "Bradycardia with hypertension is classic anticoagulant bleed."}]'::jsonb, '["b"]'::jsonb, 'Correct because Signs of internal bleeding include low BP, high HR, melena, hematuria, and severe headache suggesting intracranial bleed. Combine hemodynamic and symptom clues for early detection.', 'Anticoagulants - NCLEX', false, 18, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "dabigatran profile" in Anticoagulants?', 'In rapid prioritization, which statement is most consistent with "dabigatran profile" in Anticoagulants?', '[{"id": "a", "text": "Heparin requires 2–5 days to start working."}, {"id": "b", "text": "Both drugs are monitored with same lab."}, {"id": "c", "text": "Dabigatran is factor Xa inhibitor."}, {"id": "d", "text": "Dabigatran is direct thrombin inhibitor."}]'::jsonb, '["d"]'::jsonb, 'Correct because Dabigatran is a direct thrombin inhibitor; monitor renal function and reverse with idarucizumab. Match class and antidote accurately in urgent reversal decisions.', 'Anticoagulants - NCLEX', false, 19, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "factor Xa inhibitors profile" in Anticoagulants would the nurse recognize as correct?', 'Which conclusion about "factor Xa inhibitors profile" in Anticoagulants would the nurse recognize as correct?', '[{"id": "a", "text": "Both drugs are monitored with same lab."}, {"id": "b", "text": "Anticoagulants do not require routine monitoring."}, {"id": "c", "text": "Rivaroxaban/apixaban are factor Xa inhibitors."}, {"id": "d", "text": "Xa inhibitors are monitored by daily INR."}]'::jsonb, '["c"]'::jsonb, 'Correct because Rivaroxaban and apixaban are factor Xa inhibitors; monitor renal function/CBC and reverse with andexanet alfa. Differentiate Xa inhibitor reversal from other anticoagulants.', 'Anticoagulants - NCLEX', false, 20, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Anticoagulants note, which statement about "enoxaparin profile" is most accurate?', 'According to the Anticoagulants note, which statement about "enoxaparin profile" is most accurate?', '[{"id": "a", "text": "Anticoagulants do not require routine monitoring."}, {"id": "b", "text": "aPTT is the primary warfarin monitoring test."}, {"id": "c", "text": "Understand that reversal is partial, not complete."}, {"id": "d", "text": "Enoxaparin is fully reversed by vitamin K."}]'::jsonb, '["c"]'::jsonb, 'Correct because Enoxaparin is LMWH with anti-Xa monitoring if needed; protamine provides partial reversal. Understand that reversal is partial, not complete.', 'Anticoagulants - NCLEX', false, 21, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "lab-memory rule" in Anticoagulants. Which statement is correct?', 'The nurse is reviewing "lab-memory rule" in Anticoagulants. Which statement is correct?', '[{"id": "a", "text": "Therapeutic heparin aPTT is below 20 sec."}, {"id": "b", "text": "Use mnemonic for rapid exam-time lab matching."}, {"id": "c", "text": "Warfarin pairs only with anti-Xa."}, {"id": "d", "text": "aPTT is the primary warfarin monitoring test."}]'::jsonb, '["b"]'::jsonb, 'Correct because Memory cue: H for Heparin equals aPTT; W for Warfarin equals INR. Use mnemonic for rapid exam-time lab matching.', 'Anticoagulants - NCLEX', false, 22, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "monitoring distinction" in Anticoagulants?', 'Which clinical judgment is most accurate regarding "monitoring distinction" in Anticoagulants?', '[{"id": "a", "text": "Heparin titration uses q6h aPTT checks."}, {"id": "b", "text": "INR goal for most patients is below 1."}, {"id": "c", "text": "Warfarin is only used during surgery."}, {"id": "d", "text": "Both drugs are monitored with same lab."}]'::jsonb, '["a"]'::jsonb, 'Correct because Warfarin monitoring is INR/PT only, while heparin titration requires frequent aPTT checks every 6 hours. Do not interchange heparin and warfarin monitoring labs.', 'Anticoagulants - NCLEX', false, 23, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "integrated anticoagulant safety" in Anticoagulants?', 'In rapid prioritization, which statement is most consistent with "integrated anticoagulant safety" in Anticoagulants?', '[{"id": "a", "text": "Heparin requires 2–5 days to start working."}, {"id": "b", "text": "Warfarin has one fixed INR for all patients."}, {"id": "c", "text": "Anticoagulants do not require routine monitoring."}, {"id": "d", "text": "Correct lab-drug matching is central to safety."}]'::jsonb, '["d"]'::jsonb, 'Correct because Safe anticoagulant care requires correct lab-drug pairing, bleeding surveillance, antidote readiness, and structured escalation. Most preventable harm comes from delayed recognition and delayed response.', 'Anticoagulants - NCLEX', false, 24, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "aPTT role" in Anticoagulants would the nurse recognize as correct?', 'Which conclusion about "aPTT role" in Anticoagulants would the nurse recognize as correct?', '[{"id": "a", "text": "Antidote planning is unnecessary when labs are elevated."}, {"id": "b", "text": "aPTT is the primary warfarin monitoring test."}, {"id": "c", "text": "Trend aPTT during heparin titration to avoid under- or over-anticoagulation."}, {"id": "d", "text": "Blood pressure alone is enough for all anticoagulant safety decisions."}]'::jsonb, '["c"]'::jsonb, 'Correct because aPTT monitors heparin therapy; normal is about 30–40 sec and therapeutic heparin range is 45–80 sec. Trend aPTT during heparin titration to avoid under- or over-anticoagulation.', 'Anticoagulants - NCLEX', false, 25, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Anticoagulants note, which statement about "PT/INR role" is most accurate?', 'According to the Anticoagulants note, which statement about "PT/INR role" is most accurate?', '[{"id": "a", "text": "Vitamin K intake has no effect on warfarin."}, {"id": "b", "text": "Continue infusion and recheck next shift."}, {"id": "c", "text": "PT is associated with warfarin monitoring."}, {"id": "d", "text": "INR goal for most patients is below 1."}]'::jsonb, '["c"]'::jsonb, 'Correct because PT/INR monitor warfarin; INR therapeutic range is 2–3 for most indications. Use INR trends to guide safe warfarin dosing.', 'Anticoagulants - NCLEX', false, 26, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "heparin basics" in Anticoagulants. Which statement is correct?', 'The nurse is reviewing "heparin basics" in Anticoagulants. Which statement is correct?', '[{"id": "a", "text": "Antidote planning is unnecessary when labs are elevated."}, {"id": "b", "text": "Heparin is given IV or SubQ, has immediate IV onset, and is used for DVT, PE, ACS, dialysis, and perioperative prevention."}, {"id": "c", "text": "Blood pressure alone is enough for all anticoagulant safety decisions."}, {"id": "d", "text": "Heparin requires 2–5 days to start working."}]'::jsonb, '["b"]'::jsonb, 'Correct because Heparin is given IV or SubQ, has immediate IV onset, and is used for DVT, PE, ACS, dialysis, and perioperative prevention. Heparin is chosen when rapid anticoagulation is needed.', 'Anticoagulants - NCLEX', false, 27, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "heparin antidote" in Anticoagulants?', 'Which clinical judgment is most accurate regarding "heparin antidote" in Anticoagulants?', '[{"id": "a", "text": "Warfarin is only used during surgery."}, {"id": "b", "text": "Vitamin K is the heparin antidote."}, {"id": "c", "text": "Protamine sulfate reverses heparin."}, {"id": "d", "text": "Warfarin has immediate IV onset."}]'::jsonb, '["c"]'::jsonb, 'Correct because Protamine sulfate is the antidote for heparin. Prepare protamine quickly when significant heparin-associated bleeding risk is present.', 'Anticoagulants - NCLEX', false, 28, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "aPTT above 80" in Anticoagulants?', 'In rapid prioritization, which statement is most consistent with "aPTT above 80" in Anticoagulants?', '[{"id": "a", "text": "Follow sequence: stop, assess, prepare, call."}, {"id": "b", "text": "Warfarin has one fixed INR for all patients."}, {"id": "c", "text": "Stop heparin the same day warfarin starts."}, {"id": "d", "text": "Continue infusion and recheck next shift."}]'::jsonb, '["a"]'::jsonb, 'Correct because If aPTT exceeds 80 sec: stop infusion, assess vitals for bleeding, prepare protamine, then notify provider before giving antidote. Follow sequence: stop, assess, prepare, call.', 'Anticoagulants - NCLEX', false, 29, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "HIT recognition" in Anticoagulants would the nurse recognize as correct?', 'Which conclusion about "HIT recognition" in Anticoagulants would the nurse recognize as correct?', '[{"id": "a", "text": "Blood pressure alone is enough for all anticoagulant safety decisions."}, {"id": "b", "text": "HIT increases clotting risk paradoxically despite thrombocytopenia."}, {"id": "c", "text": "Continue heparin despite HIT signs."}, {"id": "d", "text": "Antidote planning is unnecessary when labs are elevated."}]'::jsonb, '["b"]'::jsonb, 'Correct because HIT is suspected when platelets drop more than 50% on heparin; stop heparin and switch to argatroban. HIT increases clotting risk paradoxically despite thrombocytopenia.', 'Anticoagulants - NCLEX', false, 30, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Anticoagulants note, which statement about "warfarin basics" is most accurate?', 'According to the Anticoagulants note, which statement about "warfarin basics" is most accurate?', '[{"id": "a", "text": "Warfarin monitoring is discontinued once stable."}, {"id": "b", "text": "Vitamin K intake has no effect on warfarin."}, {"id": "c", "text": "Warfarin is used for long-term anticoagulation."}, {"id": "d", "text": "Warfarin is only used during surgery."}]'::jsonb, '["c"]'::jsonb, 'Correct because Warfarin is oral and has delayed onset of 2–5 days, so it is used for long-term anticoagulation. Delayed onset drives need for bridging in acute clot treatment.', 'Anticoagulants - NCLEX', false, 31, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "warfarin therapeutic range" in Anticoagulants. Which statement is correct?', 'The nurse is reviewing "warfarin therapeutic range" in Anticoagulants. Which statement is correct?', '[{"id": "a", "text": "Valve patients often require higher anticoagulation intensity."}, {"id": "b", "text": "Warfarin has one fixed INR for all patients."}, {"id": "c", "text": "Blood pressure alone is enough for all anticoagulant safety decisions."}, {"id": "d", "text": "Antidote planning is unnecessary when labs are elevated."}]'::jsonb, '["a"]'::jsonb, 'Correct because Therapeutic INR is usually 2–3, but mechanical heart valves often target 2.5–3.5. Valve patients often require higher anticoagulation intensity.', 'Anticoagulants - NCLEX', false, 32, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "warfarin antidote" in Anticoagulants?', 'Which clinical judgment is most accurate regarding "warfarin antidote" in Anticoagulants?', '[{"id": "a", "text": "Andexanet alfa reverses warfarin."}, {"id": "b", "text": "Bleeding signs can be ignored if INR is therapeutic."}, {"id": "c", "text": "Antidote planning is unnecessary when labs are elevated."}, {"id": "d", "text": "Know warfarin-vitamin K pair for rapid NCLEX decisions."}]'::jsonb, '["d"]'::jsonb, 'Correct because Vitamin K (phytonadione) is the reversal agent for warfarin. Know warfarin-vitamin K pair for rapid NCLEX decisions.', 'Anticoagulants - NCLEX', false, 33, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "warfarin teaching vitamin K" in Anticoagulants?', 'In rapid prioritization, which statement is most consistent with "warfarin teaching vitamin K" in Anticoagulants?', '[{"id": "a", "text": "Diet changes can alter warfarin effect."}, {"id": "b", "text": "Leafy greens must be eliminated forever."}, {"id": "c", "text": "Overlap is unnecessary if INR is pending."}, {"id": "d", "text": "Heparin stops before INR reaches goal."}]'::jsonb, '["a"]'::jsonb, 'Correct because Patients should keep vitamin K intake consistent rather than eliminating leafy greens entirely. Diet consistency prevents INR instability.', 'Anticoagulants - NCLEX', false, 34, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "warfarin teaching interactions" in Anticoagulants would the nurse recognize as correct?', 'Which conclusion about "warfarin teaching interactions" in Anticoagulants would the nurse recognize as correct?', '[{"id": "a", "text": "Grapefruit lowers warfarin effect safely."}, {"id": "b", "text": "Heparin stops before INR reaches goal."}, {"id": "c", "text": "Heparin stops after one therapeutic INR."}, {"id": "d", "text": "Interaction teaching reduces bleeding risk."}]'::jsonb, '["d"]'::jsonb, 'Correct because Avoid NSAIDs and grapefruit while on warfarin due to increased bleeding risk or level changes. Medication/food interaction review is a safety essential.', 'Anticoagulants - NCLEX', false, 35, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Anticoagulants note, which statement about "warfarin bleeding teaching" is most accurate?', 'According to the Anticoagulants note, which statement about "warfarin bleeding teaching" is most accurate?', '[{"id": "a", "text": "Medical alert ID is unnecessary."}, {"id": "b", "text": "INR should be checked yearly only."}, {"id": "c", "text": "Xa inhibitors are monitored by daily INR."}, {"id": "d", "text": "Medical alert bracelet is recommended."}]'::jsonb, '["d"]'::jsonb, 'Correct because Teach patients to report unusual bleeding, hematuria, or blood in stool and wear a medical alert bracelet. Early bleeding recognition prevents severe complications.', 'Anticoagulants - NCLEX', false, 36, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "bridge overlap duration" in Anticoagulants. Which statement is correct?', 'The nurse is reviewing "bridge overlap duration" in Anticoagulants. Which statement is correct?', '[{"id": "a", "text": "Give antidote before assessment."}, {"id": "b", "text": "Overlap is unnecessary if INR is pending."}, {"id": "c", "text": "Enoxaparin is monitored by INR only."}, {"id": "d", "text": "Warfarin delay necessitates overlap."}]'::jsonb, '["d"]'::jsonb, 'Correct because When transitioning heparin to warfarin, overlap both drugs for at least 5–7 days. Bridge prevents gaps in anticoagulation while warfarin effect develops.', 'Anticoagulants - NCLEX', false, 37, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "bridge discontinuation rule" in Anticoagulants?', 'Which clinical judgment is most accurate regarding "bridge discontinuation rule" in Anticoagulants?', '[{"id": "a", "text": "Therapeutic INR must persist two consecutive days."}, {"id": "b", "text": "Heparin stops after one therapeutic INR."}, {"id": "c", "text": "Call provider before stopping active infusion."}, {"id": "d", "text": "Antidote planning is unnecessary when labs are elevated."}]'::jsonb, '["a"]'::jsonb, 'Correct because Do not stop heparin until INR is therapeutic 2–3 for two consecutive days. Require stable therapeutic INR before removing rapid-acting anticoagulant.', 'Anticoagulants - NCLEX', false, 38, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "stable INR follow-up" in Anticoagulants?', 'In rapid prioritization, which statement is most consistent with "stable INR follow-up" in Anticoagulants?', '[{"id": "a", "text": "Monitoring frequency depends on stability."}, {"id": "b", "text": "Both drugs are monitored with same lab."}, {"id": "c", "text": "Hematuria is expected and not concerning."}, {"id": "d", "text": "Warfarin monitoring is discontinued once stable."}]'::jsonb, '["a"]'::jsonb, 'Correct because Once INR is stable, warfarin monitoring can be every 3 weeks per note. Stable outpatient monitoring still requires routine checks.', 'Anticoagulants - NCLEX', false, 39, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "critical high-risk thresholds" in Anticoagulants would the nurse recognize as correct?', 'Which conclusion about "critical high-risk thresholds" in Anticoagulants would the nurse recognize as correct?', '[{"id": "a", "text": "Anticoagulants do not require routine monitoring."}, {"id": "b", "text": "Both trigger urgent intervention sequence."}, {"id": "c", "text": "aPTT >80 sec suggests under-anticoagulation."}, {"id": "d", "text": "Xa inhibitors are monitored by daily INR."}]'::jsonb, '["b"]'::jsonb, 'Correct because INR greater than 4 or aPTT greater than 80 sec indicates high hemorrhage risk and immediate intervention. Recognize threshold triggers for urgent safety response.', 'Anticoagulants - NCLEX', false, 40, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Anticoagulants note, which statement about "STOP ASSESS PREPARE CALL" is most accurate?', 'According to the Anticoagulants note, which statement about "STOP ASSESS PREPARE CALL" is most accurate?', '[{"id": "a", "text": "Give antidote before assessment."}, {"id": "b", "text": "Prepare antidote then call provider."}, {"id": "c", "text": "Therapeutic heparin aPTT is below 20 sec."}, {"id": "d", "text": "Enoxaparin is monitored by INR only."}]'::jsonb, '["b"]'::jsonb, 'Correct because NCLEX priority order for suspected internal bleeding is STOP anticoagulant, ASSESS vitals/bleeding, PREPARE antidote, then CALL provider. Sequence discipline improves emergency anticoagulant safety.', 'Anticoagulants - NCLEX', false, 41, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "internal bleeding signs" in Anticoagulants. Which statement is correct?', 'The nurse is reviewing "internal bleeding signs" in Anticoagulants. Which statement is correct?', '[{"id": "a", "text": "Low BP plus high HR can indicate internal bleeding."}, {"id": "b", "text": "Bradycardia with hypertension is classic anticoagulant bleed."}, {"id": "c", "text": "Enoxaparin is fully reversed by vitamin K."}, {"id": "d", "text": "Antidote planning is unnecessary when labs are elevated."}]'::jsonb, '["a"]'::jsonb, 'Correct because Signs of internal bleeding include low BP, high HR, melena, hematuria, and severe headache suggesting intracranial bleed. Combine hemodynamic and symptom clues for early detection.', 'Anticoagulants - NCLEX', false, 42, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "dabigatran profile" in Anticoagulants?', 'Which clinical judgment is most accurate regarding "dabigatran profile" in Anticoagulants?', '[{"id": "a", "text": "Match class and antidote accurately in urgent reversal decisions."}, {"id": "b", "text": "Antidote planning is unnecessary when labs are elevated."}, {"id": "c", "text": "Dabigatran is factor Xa inhibitor."}, {"id": "d", "text": "Blood pressure alone is enough for all anticoagulant safety decisions."}]'::jsonb, '["a"]'::jsonb, 'Correct because Dabigatran is a direct thrombin inhibitor; monitor renal function and reverse with idarucizumab. Match class and antidote accurately in urgent reversal decisions.', 'Anticoagulants - NCLEX', false, 43, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "factor Xa inhibitors profile" in Anticoagulants?', 'In rapid prioritization, which statement is most consistent with "factor Xa inhibitors profile" in Anticoagulants?', '[{"id": "a", "text": "Blood pressure alone is enough for all anticoagulant safety decisions."}, {"id": "b", "text": "Xa inhibitors are monitored by daily INR."}, {"id": "c", "text": "Antidote planning is unnecessary when labs are elevated."}, {"id": "d", "text": "Differentiate Xa inhibitor reversal from other anticoagulants."}]'::jsonb, '["d"]'::jsonb, 'Correct because Rivaroxaban and apixaban are factor Xa inhibitors; monitor renal function/CBC and reverse with andexanet alfa. Differentiate Xa inhibitor reversal from other anticoagulants.', 'Anticoagulants - NCLEX', false, 44, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "enoxaparin profile" in Anticoagulants would the nurse recognize as correct?', 'Which conclusion about "enoxaparin profile" in Anticoagulants would the nurse recognize as correct?', '[{"id": "a", "text": "Understand that reversal is partial, not complete."}, {"id": "b", "text": "Enoxaparin is fully reversed by vitamin K."}, {"id": "c", "text": "Antidote planning is unnecessary when labs are elevated."}, {"id": "d", "text": "Anticoagulants do not require routine monitoring."}]'::jsonb, '["a"]'::jsonb, 'Correct because Enoxaparin is LMWH with anti-Xa monitoring if needed; protamine provides partial reversal. Understand that reversal is partial, not complete.', 'Anticoagulants - NCLEX', false, 45, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Anticoagulants note, which statement about "lab-memory rule" is most accurate?', 'According to the Anticoagulants note, which statement about "lab-memory rule" is most accurate?', '[{"id": "a", "text": "Antidote planning is unnecessary when labs are elevated."}, {"id": "b", "text": "Memory cue: H for Heparin equals aPTT; W for Warfarin equals INR."}, {"id": "c", "text": "Blood pressure alone is enough for all anticoagulant safety decisions."}, {"id": "d", "text": "Warfarin pairs only with anti-Xa."}]'::jsonb, '["b"]'::jsonb, 'Correct because Memory cue: H for Heparin equals aPTT; W for Warfarin equals INR. Use mnemonic for rapid exam-time lab matching.', 'Anticoagulants - NCLEX', false, 46, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "monitoring distinction" in Anticoagulants. Which statement is correct?', 'The nurse is reviewing "monitoring distinction" in Anticoagulants. Which statement is correct?', '[{"id": "a", "text": "Warfarin is monitored by aPTT only."}, {"id": "b", "text": "Both drugs are monitored with same lab."}, {"id": "c", "text": "Monitoring strategy differs by drug."}, {"id": "d", "text": "Warfarin is only used during surgery."}]'::jsonb, '["c"]'::jsonb, 'Correct because Warfarin monitoring is INR/PT only, while heparin titration requires frequent aPTT checks every 6 hours. Do not interchange heparin and warfarin monitoring labs.', 'Anticoagulants - NCLEX', false, 47, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "integrated anticoagulant safety" in Anticoagulants?', 'Which clinical judgment is most accurate regarding "integrated anticoagulant safety" in Anticoagulants?', '[{"id": "a", "text": "Heparin requires 2–5 days to start working."}, {"id": "b", "text": "Bleeding signs require immediate action."}, {"id": "c", "text": "Escalation sequence is optional."}, {"id": "d", "text": "Mechanical valve INR target is below 2."}]'::jsonb, '["b"]'::jsonb, 'Correct because Safe anticoagulant care requires correct lab-drug pairing, bleeding surveillance, antidote readiness, and structured escalation. Most preventable harm comes from delayed recognition and delayed response.', 'Anticoagulants - NCLEX', false, 48, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "aPTT role" in Anticoagulants?', 'In rapid prioritization, which statement is most consistent with "aPTT role" in Anticoagulants?', '[{"id": "a", "text": "Vitamin K is the heparin antidote."}, {"id": "b", "text": "Therapeutic heparin aPTT is below 20 sec."}, {"id": "c", "text": "Therapeutic heparin aPTT is 45–80 sec."}, {"id": "d", "text": "Continue infusion and recheck next shift."}]'::jsonb, '["c"]'::jsonb, 'Correct because aPTT monitors heparin therapy; normal is about 30–40 sec and therapeutic heparin range is 45–80 sec. Trend aPTT during heparin titration to avoid under- or over-anticoagulation.', 'Anticoagulants - NCLEX', false, 49, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "PT/INR role" in Anticoagulants would the nurse recognize as correct?', 'Which conclusion about "PT/INR role" in Anticoagulants would the nurse recognize as correct?', '[{"id": "a", "text": "Warfarin is monitored by aPTT only."}, {"id": "b", "text": "Give antidote before any assessment."}, {"id": "c", "text": "INR is used for warfarin monitoring."}, {"id": "d", "text": "INR goal for most patients is below 1."}]'::jsonb, '["c"]'::jsonb, 'Correct because PT/INR monitor warfarin; INR therapeutic range is 2–3 for most indications. Use INR trends to guide safe warfarin dosing.', 'Anticoagulants - NCLEX', false, 50, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "aPTT role" in Anticoagulants are correct? (Select all that apply)', 'Which statements about "aPTT role" in Anticoagulants are correct? (Select all that apply)', '[{"id": "a", "text": "Therapeutic heparin aPTT is below 20 sec."}, {"id": "b", "text": "Normal aPTT is around 30–40 sec."}, {"id": "c", "text": "aPTT is used to monitor heparin."}, {"id": "d", "text": "Therapeutic heparin aPTT is 45–80 sec."}, {"id": "e", "text": "aPTT is the primary warfarin monitoring test."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: aPTT monitors heparin therapy; normal is about 30–40 sec and therapeutic heparin range is 45–80 sec.', 'Anticoagulants - NCLEX', true, 51, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Anticoagulants, which findings or actions relate to "PT/INR role"? (Select all that apply)', 'For Anticoagulants, which findings or actions relate to "PT/INR role"? (Select all that apply)', '[{"id": "a", "text": "INR is used for warfarin monitoring."}, {"id": "b", "text": "Typical therapeutic INR is 2–3."}, {"id": "c", "text": "INR goal for most patients is below 1."}, {"id": "d", "text": "PT is associated with warfarin monitoring."}, {"id": "e", "text": "Warfarin is monitored by aPTT only."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: PT/INR monitor warfarin; INR therapeutic range is 2–3 for most indications.', 'Anticoagulants - NCLEX', true, 52, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "heparin basics" in Anticoagulants? (Select all that apply)', 'The nurse is planning care. Which items apply to "heparin basics" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Heparin requires 2–5 days to start working."}, {"id": "b", "text": "Heparin is oral only."}, {"id": "c", "text": "DVT/PE/ACS are listed uses."}, {"id": "d", "text": "Heparin can be IV or SubQ."}, {"id": "e", "text": "IV heparin onset is immediate."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Heparin is given IV or SubQ, has immediate IV onset, and is used for DVT, PE, ACS, dialysis, and perioperative prevention.', 'Anticoagulants - NCLEX', true, 53, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "heparin antidote" in Anticoagulants? (Select all that apply)', 'Which of the following are consistent with "heparin antidote" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Idarucizumab reverses heparin."}, {"id": "b", "text": "Protamine sulfate reverses heparin."}, {"id": "c", "text": "Protamine is linked with heparin overdose management."}, {"id": "d", "text": "Heparin has a named antidote."}, {"id": "e", "text": "Vitamin K is the heparin antidote."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Protamine sulfate is the antidote for heparin.', 'Anticoagulants - NCLEX', true, 54, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "aPTT above 80" in Anticoagulants? (Select all that apply)', 'During reassessment, which observations align with "aPTT above 80" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Notify provider before antidote administration."}, {"id": "b", "text": "Continue infusion and recheck next shift."}, {"id": "c", "text": "Stop heparin infusion if aPTT is >80 sec."}, {"id": "d", "text": "Give antidote before any assessment."}, {"id": "e", "text": "Assess for bleeding signs like low BP and high HR."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: If aPTT exceeds 80 sec: stop infusion, assess vitals for bleeding, prepare protamine, then notify provider before giving antidote.', 'Anticoagulants - NCLEX', true, 55, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "HIT recognition" in Anticoagulants are correct? (Select all that apply)', 'Which statements about "HIT recognition" in Anticoagulants are correct? (Select all that apply)', '[{"id": "a", "text": "Platelet drop >50% suggests HIT."}, {"id": "b", "text": "Heparin should be stopped in suspected HIT."}, {"id": "c", "text": "Continue heparin despite HIT signs."}, {"id": "d", "text": "Argatroban is listed as alternative."}, {"id": "e", "text": "HIT primarily lowers clot risk."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: HIT is suspected when platelets drop more than 50% on heparin; stop heparin and switch to argatroban.', 'Anticoagulants - NCLEX', true, 56, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Anticoagulants, which findings or actions relate to "warfarin basics"? (Select all that apply)', 'For Anticoagulants, which findings or actions relate to "warfarin basics"? (Select all that apply)', '[{"id": "a", "text": "Warfarin is only used during surgery."}, {"id": "b", "text": "Warfarin is used for long-term anticoagulation."}, {"id": "c", "text": "Warfarin has immediate IV onset."}, {"id": "d", "text": "Warfarin onset is delayed 2–5 days."}, {"id": "e", "text": "Warfarin is oral."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Warfarin is oral and has delayed onset of 2–5 days, so it is used for long-term anticoagulation.', 'Anticoagulants - NCLEX', true, 57, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "warfarin therapeutic range" in Anticoagulants? (Select all that apply)', 'The nurse is planning care. Which items apply to "warfarin therapeutic range" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Mechanical valves may require INR 2.5–3.5."}, {"id": "b", "text": "Mechanical valve INR target is below 2."}, {"id": "c", "text": "INR goal differs by indication."}, {"id": "d", "text": "Warfarin has one fixed INR for all patients."}, {"id": "e", "text": "Usual INR target is 2–3."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Therapeutic INR is usually 2–3, but mechanical heart valves often target 2.5–3.5.', 'Anticoagulants - NCLEX', true, 58, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "warfarin antidote" in Anticoagulants? (Select all that apply)', 'Which of the following are consistent with "warfarin antidote" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Protamine reverses warfarin."}, {"id": "b", "text": "Andexanet alfa reverses warfarin."}, {"id": "c", "text": "Warfarin has specific antidote listed."}, {"id": "d", "text": "Phytonadione is vitamin K name in note."}, {"id": "e", "text": "Vitamin K reverses warfarin."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Vitamin K (phytonadione) is the reversal agent for warfarin.', 'Anticoagulants - NCLEX', true, 59, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "warfarin teaching vitamin K" in Anticoagulants? (Select all that apply)', 'During reassessment, which observations align with "warfarin teaching vitamin K" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Diet changes can alter warfarin effect."}, {"id": "b", "text": "Vitamin K intake has no effect on warfarin."}, {"id": "c", "text": "Patients should not completely avoid leafy greens."}, {"id": "d", "text": "Vitamin K intake should be consistent."}, {"id": "e", "text": "Leafy greens must be eliminated forever."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Patients should keep vitamin K intake consistent rather than eliminating leafy greens entirely.', 'Anticoagulants - NCLEX', true, 60, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "warfarin teaching interactions" in Anticoagulants are correct? (Select all that apply)', 'Which statements about "warfarin teaching interactions" in Anticoagulants are correct? (Select all that apply)', '[{"id": "a", "text": "Interaction teaching reduces bleeding risk."}, {"id": "b", "text": "Grapefruit is listed to avoid."}, {"id": "c", "text": "Warfarin patients should take NSAIDs for routine pain."}, {"id": "d", "text": "Grapefruit lowers warfarin effect safely."}, {"id": "e", "text": "NSAIDs should be avoided with warfarin."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Avoid NSAIDs and grapefruit while on warfarin due to increased bleeding risk or level changes.', 'Anticoagulants - NCLEX', true, 61, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Anticoagulants, which findings or actions relate to "warfarin bleeding teaching"? (Select all that apply)', 'For Anticoagulants, which findings or actions relate to "warfarin bleeding teaching"? (Select all that apply)', '[{"id": "a", "text": "Blood in urine/stool is concerning."}, {"id": "b", "text": "Medical alert ID is unnecessary."}, {"id": "c", "text": "Medical alert bracelet is recommended."}, {"id": "d", "text": "Bleeding signs can be ignored if INR is therapeutic."}, {"id": "e", "text": "Report unusual bleeding immediately."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Teach patients to report unusual bleeding, hematuria, or blood in stool and wear a medical alert bracelet.', 'Anticoagulants - NCLEX', true, 62, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "bridge overlap duration" in Anticoagulants? (Select all that apply)', 'The nurse is planning care. Which items apply to "bridge overlap duration" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Stop heparin the same day warfarin starts."}, {"id": "b", "text": "Overlap is unnecessary if INR is pending."}, {"id": "c", "text": "Heparin provides immediate effect during bridge."}, {"id": "d", "text": "Warfarin delay necessitates overlap."}, {"id": "e", "text": "Heparin-warfarin overlap should be 5–7 days minimum."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: When transitioning heparin to warfarin, overlap both drugs for at least 5–7 days.', 'Anticoagulants - NCLEX', true, 63, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "bridge discontinuation rule" in Anticoagulants? (Select all that apply)', 'Which of the following are consistent with "bridge discontinuation rule" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Heparin continues until INR is therapeutic."}, {"id": "b", "text": "Target INR for this bridge is 2–3."}, {"id": "c", "text": "Heparin stops after one therapeutic INR."}, {"id": "d", "text": "Therapeutic INR must persist two consecutive days."}, {"id": "e", "text": "Heparin stops before INR reaches goal."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Do not stop heparin until INR is therapeutic 2–3 for two consecutive days.', 'Anticoagulants - NCLEX', true, 64, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "stable INR follow-up" in Anticoagulants? (Select all that apply)', 'During reassessment, which observations align with "stable INR follow-up" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Warfarin monitoring is discontinued once stable."}, {"id": "b", "text": "INR should be checked yearly only."}, {"id": "c", "text": "INR monitoring continues long-term."}, {"id": "d", "text": "Monitoring frequency depends on stability."}, {"id": "e", "text": "Stable warfarin INR checks can be every 3 weeks."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Once INR is stable, warfarin monitoring can be every 3 weeks per note.', 'Anticoagulants - NCLEX', true, 65, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "critical high-risk thresholds" in Anticoagulants are correct? (Select all that apply)', 'Which statements about "critical high-risk thresholds" in Anticoagulants are correct? (Select all that apply)', '[{"id": "a", "text": "aPTT >80 sec is high hemorrhage risk in note."}, {"id": "b", "text": "INR >4 is high hemorrhage risk in note."}, {"id": "c", "text": "aPTT >80 sec suggests under-anticoagulation."}, {"id": "d", "text": "INR 4.5 is reassuring."}, {"id": "e", "text": "Both trigger urgent intervention sequence."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: INR greater than 4 or aPTT greater than 80 sec indicates high hemorrhage risk and immediate intervention.', 'Anticoagulants - NCLEX', true, 66, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Anticoagulants, which findings or actions relate to "STOP ASSESS PREPARE CALL"? (Select all that apply)', 'For Anticoagulants, which findings or actions relate to "STOP ASSESS PREPARE CALL"? (Select all that apply)', '[{"id": "a", "text": "Give antidote before assessment."}, {"id": "b", "text": "Call provider before stopping active infusion."}, {"id": "c", "text": "Stop anticoagulant first."}, {"id": "d", "text": "Assess for low BP/high HR/pallor/bleeding."}, {"id": "e", "text": "Prepare antidote then call provider."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: NCLEX priority order for suspected internal bleeding is STOP anticoagulant, ASSESS vitals/bleeding, PREPARE antidote, then CALL provider.', 'Anticoagulants - NCLEX', true, 67, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "internal bleeding signs" in Anticoagulants? (Select all that apply)', 'The nurse is planning care. Which items apply to "internal bleeding signs" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Bradycardia with hypertension is classic anticoagulant bleed."}, {"id": "b", "text": "Hematuria is expected and not concerning."}, {"id": "c", "text": "Melena and hematuria are warning signs."}, {"id": "d", "text": "Severe headache may indicate intracranial bleed."}, {"id": "e", "text": "Low BP plus high HR can indicate internal bleeding."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Signs of internal bleeding include low BP, high HR, melena, hematuria, and severe headache suggesting intracranial bleed.', 'Anticoagulants - NCLEX', true, 68, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "dabigatran profile" in Anticoagulants? (Select all that apply)', 'Which of the following are consistent with "dabigatran profile" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Dabigatran is direct thrombin inhibitor."}, {"id": "b", "text": "Idarucizumab is antidote."}, {"id": "c", "text": "Dabigatran is factor Xa inhibitor."}, {"id": "d", "text": "Protamine is dabigatran antidote."}, {"id": "e", "text": "Renal function monitoring is listed."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Dabigatran is a direct thrombin inhibitor; monitor renal function and reverse with idarucizumab.', 'Anticoagulants - NCLEX', true, 69, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "factor Xa inhibitors profile" in Anticoagulants? (Select all that apply)', 'During reassessment, which observations align with "factor Xa inhibitors profile" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Rivaroxaban/apixaban are factor Xa inhibitors."}, {"id": "b", "text": "Andexanet alfa is their listed antidote."}, {"id": "c", "text": "Idarucizumab reverses apixaban."}, {"id": "d", "text": "Xa inhibitors are monitored by daily INR."}, {"id": "e", "text": "Renal function and CBC monitoring are listed."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Rivaroxaban and apixaban are factor Xa inhibitors; monitor renal function/CBC and reverse with andexanet alfa.', 'Anticoagulants - NCLEX', true, 70, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "enoxaparin profile" in Anticoagulants are correct? (Select all that apply)', 'Which statements about "enoxaparin profile" in Anticoagulants are correct? (Select all that apply)', '[{"id": "a", "text": "Enoxaparin is fully reversed by vitamin K."}, {"id": "b", "text": "Anti-Xa may be checked when needed."}, {"id": "c", "text": "Enoxaparin is LMWH."}, {"id": "d", "text": "Enoxaparin is monitored by INR only."}, {"id": "e", "text": "Protamine gives partial reversal."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Enoxaparin is LMWH with anti-Xa monitoring if needed; protamine provides partial reversal.', 'Anticoagulants - NCLEX', true, 71, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Anticoagulants, which findings or actions relate to "lab-memory rule"? (Select all that apply)', 'For Anticoagulants, which findings or actions relate to "lab-memory rule"? (Select all that apply)', '[{"id": "a", "text": "Mnemonic supports quick recall."}, {"id": "b", "text": "Warfarin pairs with INR."}, {"id": "c", "text": "Heparin pairs with aPTT."}, {"id": "d", "text": "Heparin pairs with INR."}, {"id": "e", "text": "Warfarin pairs only with anti-Xa."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Memory cue: H for Heparin equals aPTT; W for Warfarin equals INR.', 'Anticoagulants - NCLEX', true, 72, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "monitoring distinction" in Anticoagulants? (Select all that apply)', 'The nurse is planning care. Which items apply to "monitoring distinction" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Warfarin titration uses q6h aPTT."}, {"id": "b", "text": "Monitoring strategy differs by drug."}, {"id": "c", "text": "Both drugs are monitored with same lab."}, {"id": "d", "text": "Warfarin is monitored with INR/PT."}, {"id": "e", "text": "Heparin titration uses q6h aPTT checks."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Warfarin monitoring is INR/PT only, while heparin titration requires frequent aPTT checks every 6 hours.', 'Anticoagulants - NCLEX', true, 73, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "integrated anticoagulant safety" in Anticoagulants? (Select all that apply)', 'Which of the following are consistent with "integrated anticoagulant safety" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Bleeding signs require immediate action."}, {"id": "b", "text": "Correct lab-drug matching is central to safety."}, {"id": "c", "text": "Anticoagulants do not require routine monitoring."}, {"id": "d", "text": "Antidote readiness is emphasized in NCLEX priorities."}, {"id": "e", "text": "Escalation sequence is optional."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Safe anticoagulant care requires correct lab-drug pairing, bleeding surveillance, antidote readiness, and structured escalation.', 'Anticoagulants - NCLEX', true, 74, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "aPTT role" in Anticoagulants? (Select all that apply)', 'During reassessment, which observations align with "aPTT role" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Therapeutic heparin aPTT is 45–80 sec."}, {"id": "b", "text": "aPTT is used to monitor heparin."}, {"id": "c", "text": "Normal aPTT is around 30–40 sec."}, {"id": "d", "text": "Therapeutic heparin aPTT is below 20 sec."}, {"id": "e", "text": "aPTT is the primary warfarin monitoring test."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: aPTT monitors heparin therapy; normal is about 30–40 sec and therapeutic heparin range is 45–80 sec.', 'Anticoagulants - NCLEX', true, 75, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "PT/INR role" in Anticoagulants are correct? (Select all that apply)', 'Which statements about "PT/INR role" in Anticoagulants are correct? (Select all that apply)', '[{"id": "a", "text": "Typical therapeutic INR is 2–3."}, {"id": "b", "text": "PT is associated with warfarin monitoring."}, {"id": "c", "text": "INR goal for most patients is below 1."}, {"id": "d", "text": "Warfarin is monitored by aPTT only."}, {"id": "e", "text": "INR is used for warfarin monitoring."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: PT/INR monitor warfarin; INR therapeutic range is 2–3 for most indications.', 'Anticoagulants - NCLEX', true, 76, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Anticoagulants, which findings or actions relate to "heparin basics"? (Select all that apply)', 'For Anticoagulants, which findings or actions relate to "heparin basics"? (Select all that apply)', '[{"id": "a", "text": "Heparin is oral only."}, {"id": "b", "text": "DVT/PE/ACS are listed uses."}, {"id": "c", "text": "Heparin requires 2–5 days to start working."}, {"id": "d", "text": "IV heparin onset is immediate."}, {"id": "e", "text": "Heparin can be IV or SubQ."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Heparin is given IV or SubQ, has immediate IV onset, and is used for DVT, PE, ACS, dialysis, and perioperative prevention.', 'Anticoagulants - NCLEX', true, 77, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "heparin antidote" in Anticoagulants? (Select all that apply)', 'The nurse is planning care. Which items apply to "heparin antidote" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Heparin has a named antidote."}, {"id": "b", "text": "Protamine is linked with heparin overdose management."}, {"id": "c", "text": "Protamine sulfate reverses heparin."}, {"id": "d", "text": "Idarucizumab reverses heparin."}, {"id": "e", "text": "Vitamin K is the heparin antidote."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Protamine sulfate is the antidote for heparin.', 'Anticoagulants - NCLEX', true, 78, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "aPTT above 80" in Anticoagulants? (Select all that apply)', 'Which of the following are consistent with "aPTT above 80" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Give antidote before any assessment."}, {"id": "b", "text": "Stop heparin infusion if aPTT is >80 sec."}, {"id": "c", "text": "Assess for bleeding signs like low BP and high HR."}, {"id": "d", "text": "Notify provider before antidote administration."}, {"id": "e", "text": "Continue infusion and recheck next shift."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: If aPTT exceeds 80 sec: stop infusion, assess vitals for bleeding, prepare protamine, then notify provider before giving antidote.', 'Anticoagulants - NCLEX', true, 79, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "HIT recognition" in Anticoagulants? (Select all that apply)', 'During reassessment, which observations align with "HIT recognition" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Continue heparin despite HIT signs."}, {"id": "b", "text": "HIT primarily lowers clot risk."}, {"id": "c", "text": "Argatroban is listed as alternative."}, {"id": "d", "text": "Platelet drop >50% suggests HIT."}, {"id": "e", "text": "Heparin should be stopped in suspected HIT."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: HIT is suspected when platelets drop more than 50% on heparin; stop heparin and switch to argatroban.', 'Anticoagulants - NCLEX', true, 80, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "warfarin basics" in Anticoagulants are correct? (Select all that apply)', 'Which statements about "warfarin basics" in Anticoagulants are correct? (Select all that apply)', '[{"id": "a", "text": "Warfarin is used for long-term anticoagulation."}, {"id": "b", "text": "Warfarin onset is delayed 2–5 days."}, {"id": "c", "text": "Warfarin is only used during surgery."}, {"id": "d", "text": "Warfarin has immediate IV onset."}, {"id": "e", "text": "Warfarin is oral."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Warfarin is oral and has delayed onset of 2–5 days, so it is used for long-term anticoagulation.', 'Anticoagulants - NCLEX', true, 81, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Anticoagulants, which findings or actions relate to "warfarin therapeutic range"? (Select all that apply)', 'For Anticoagulants, which findings or actions relate to "warfarin therapeutic range"? (Select all that apply)', '[{"id": "a", "text": "Mechanical valves may require INR 2.5–3.5."}, {"id": "b", "text": "Warfarin has one fixed INR for all patients."}, {"id": "c", "text": "Mechanical valve INR target is below 2."}, {"id": "d", "text": "INR goal differs by indication."}, {"id": "e", "text": "Usual INR target is 2–3."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Therapeutic INR is usually 2–3, but mechanical heart valves often target 2.5–3.5.', 'Anticoagulants - NCLEX', true, 82, 1, true);
