  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "warfarin antidote" in Anticoagulants? (Select all that apply)', 'The nurse is planning care. Which items apply to "warfarin antidote" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Warfarin has specific antidote listed."}, {"id": "b", "text": "Phytonadione is vitamin K name in note."}, {"id": "c", "text": "Protamine reverses warfarin."}, {"id": "d", "text": "Vitamin K reverses warfarin."}, {"id": "e", "text": "Andexanet alfa reverses warfarin."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Vitamin K (phytonadione) is the reversal agent for warfarin.', 'Anticoagulants - NCLEX', true, 83, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "warfarin teaching vitamin K" in Anticoagulants? (Select all that apply)', 'Which of the following are consistent with "warfarin teaching vitamin K" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Vitamin K intake has no effect on warfarin."}, {"id": "b", "text": "Diet changes can alter warfarin effect."}, {"id": "c", "text": "Leafy greens must be eliminated forever."}, {"id": "d", "text": "Patients should not completely avoid leafy greens."}, {"id": "e", "text": "Vitamin K intake should be consistent."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Patients should keep vitamin K intake consistent rather than eliminating leafy greens entirely.', 'Anticoagulants - NCLEX', true, 84, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "warfarin teaching interactions" in Anticoagulants? (Select all that apply)', 'During reassessment, which observations align with "warfarin teaching interactions" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Grapefruit is listed to avoid."}, {"id": "b", "text": "Grapefruit lowers warfarin effect safely."}, {"id": "c", "text": "Warfarin patients should take NSAIDs for routine pain."}, {"id": "d", "text": "NSAIDs should be avoided with warfarin."}, {"id": "e", "text": "Interaction teaching reduces bleeding risk."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Avoid NSAIDs and grapefruit while on warfarin due to increased bleeding risk or level changes.', 'Anticoagulants - NCLEX', true, 85, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "warfarin bleeding teaching" in Anticoagulants are correct? (Select all that apply)', 'Which statements about "warfarin bleeding teaching" in Anticoagulants are correct? (Select all that apply)', '[{"id": "a", "text": "Bleeding signs can be ignored if INR is therapeutic."}, {"id": "b", "text": "Medical alert bracelet is recommended."}, {"id": "c", "text": "Blood in urine/stool is concerning."}, {"id": "d", "text": "Medical alert ID is unnecessary."}, {"id": "e", "text": "Report unusual bleeding immediately."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Teach patients to report unusual bleeding, hematuria, or blood in stool and wear a medical alert bracelet.', 'Anticoagulants - NCLEX', true, 86, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Anticoagulants, which findings or actions relate to "bridge overlap duration"? (Select all that apply)', 'For Anticoagulants, which findings or actions relate to "bridge overlap duration"? (Select all that apply)', '[{"id": "a", "text": "Heparin provides immediate effect during bridge."}, {"id": "b", "text": "Stop heparin the same day warfarin starts."}, {"id": "c", "text": "Overlap is unnecessary if INR is pending."}, {"id": "d", "text": "Heparin-warfarin overlap should be 5–7 days minimum."}, {"id": "e", "text": "Warfarin delay necessitates overlap."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: When transitioning heparin to warfarin, overlap both drugs for at least 5–7 days.', 'Anticoagulants - NCLEX', true, 87, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "bridge discontinuation rule" in Anticoagulants? (Select all that apply)', 'The nurse is planning care. Which items apply to "bridge discontinuation rule" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Heparin stops before INR reaches goal."}, {"id": "b", "text": "Heparin stops after one therapeutic INR."}, {"id": "c", "text": "Heparin continues until INR is therapeutic."}, {"id": "d", "text": "Therapeutic INR must persist two consecutive days."}, {"id": "e", "text": "Target INR for this bridge is 2–3."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Do not stop heparin until INR is therapeutic 2–3 for two consecutive days.', 'Anticoagulants - NCLEX', true, 88, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "stable INR follow-up" in Anticoagulants? (Select all that apply)', 'Which of the following are consistent with "stable INR follow-up" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Stable warfarin INR checks can be every 3 weeks."}, {"id": "b", "text": "INR monitoring continues long-term."}, {"id": "c", "text": "INR should be checked yearly only."}, {"id": "d", "text": "Monitoring frequency depends on stability."}, {"id": "e", "text": "Warfarin monitoring is discontinued once stable."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Once INR is stable, warfarin monitoring can be every 3 weeks per note.', 'Anticoagulants - NCLEX', true, 89, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "critical high-risk thresholds" in Anticoagulants? (Select all that apply)', 'During reassessment, which observations align with "critical high-risk thresholds" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Both trigger urgent intervention sequence."}, {"id": "b", "text": "aPTT >80 sec is high hemorrhage risk in note."}, {"id": "c", "text": "aPTT >80 sec suggests under-anticoagulation."}, {"id": "d", "text": "INR >4 is high hemorrhage risk in note."}, {"id": "e", "text": "INR 4.5 is reassuring."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: INR greater than 4 or aPTT greater than 80 sec indicates high hemorrhage risk and immediate intervention.', 'Anticoagulants - NCLEX', true, 90, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "STOP ASSESS PREPARE CALL" in Anticoagulants are correct? (Select all that apply)', 'Which statements about "STOP ASSESS PREPARE CALL" in Anticoagulants are correct? (Select all that apply)', '[{"id": "a", "text": "Stop anticoagulant first."}, {"id": "b", "text": "Give antidote before assessment."}, {"id": "c", "text": "Call provider before stopping active infusion."}, {"id": "d", "text": "Prepare antidote then call provider."}, {"id": "e", "text": "Assess for low BP/high HR/pallor/bleeding."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: NCLEX priority order for suspected internal bleeding is STOP anticoagulant, ASSESS vitals/bleeding, PREPARE antidote, then CALL provider.', 'Anticoagulants - NCLEX', true, 91, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Anticoagulants, which findings or actions relate to "internal bleeding signs"? (Select all that apply)', 'For Anticoagulants, which findings or actions relate to "internal bleeding signs"? (Select all that apply)', '[{"id": "a", "text": "Severe headache may indicate intracranial bleed."}, {"id": "b", "text": "Hematuria is expected and not concerning."}, {"id": "c", "text": "Melena and hematuria are warning signs."}, {"id": "d", "text": "Bradycardia with hypertension is classic anticoagulant bleed."}, {"id": "e", "text": "Low BP plus high HR can indicate internal bleeding."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Signs of internal bleeding include low BP, high HR, melena, hematuria, and severe headache suggesting intracranial bleed.', 'Anticoagulants - NCLEX', true, 92, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "dabigatran profile" in Anticoagulants? (Select all that apply)', 'The nurse is planning care. Which items apply to "dabigatran profile" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Dabigatran is direct thrombin inhibitor."}, {"id": "b", "text": "Dabigatran is factor Xa inhibitor."}, {"id": "c", "text": "Idarucizumab is antidote."}, {"id": "d", "text": "Renal function monitoring is listed."}, {"id": "e", "text": "Protamine is dabigatran antidote."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Dabigatran is a direct thrombin inhibitor; monitor renal function and reverse with idarucizumab.', 'Anticoagulants - NCLEX', true, 93, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "factor Xa inhibitors profile" in Anticoagulants? (Select all that apply)', 'Which of the following are consistent with "factor Xa inhibitors profile" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Renal function and CBC monitoring are listed."}, {"id": "b", "text": "Xa inhibitors are monitored by daily INR."}, {"id": "c", "text": "Rivaroxaban/apixaban are factor Xa inhibitors."}, {"id": "d", "text": "Idarucizumab reverses apixaban."}, {"id": "e", "text": "Andexanet alfa is their listed antidote."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Rivaroxaban and apixaban are factor Xa inhibitors; monitor renal function/CBC and reverse with andexanet alfa.', 'Anticoagulants - NCLEX', true, 94, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "enoxaparin profile" in Anticoagulants? (Select all that apply)', 'During reassessment, which observations align with "enoxaparin profile" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Enoxaparin is monitored by INR only."}, {"id": "b", "text": "Anti-Xa may be checked when needed."}, {"id": "c", "text": "Enoxaparin is LMWH."}, {"id": "d", "text": "Protamine gives partial reversal."}, {"id": "e", "text": "Enoxaparin is fully reversed by vitamin K."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Enoxaparin is LMWH with anti-Xa monitoring if needed; protamine provides partial reversal.', 'Anticoagulants - NCLEX', true, 95, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "lab-memory rule" in Anticoagulants are correct? (Select all that apply)', 'Which statements about "lab-memory rule" in Anticoagulants are correct? (Select all that apply)', '[{"id": "a", "text": "Warfarin pairs only with anti-Xa."}, {"id": "b", "text": "Mnemonic supports quick recall."}, {"id": "c", "text": "Warfarin pairs with INR."}, {"id": "d", "text": "Heparin pairs with aPTT."}, {"id": "e", "text": "Heparin pairs with INR."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Memory cue: H for Heparin equals aPTT; W for Warfarin equals INR.', 'Anticoagulants - NCLEX', true, 96, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Anticoagulants, which findings or actions relate to "monitoring distinction"? (Select all that apply)', 'For Anticoagulants, which findings or actions relate to "monitoring distinction"? (Select all that apply)', '[{"id": "a", "text": "Heparin titration uses q6h aPTT checks."}, {"id": "b", "text": "Warfarin titration uses q6h aPTT."}, {"id": "c", "text": "Warfarin is monitored with INR/PT."}, {"id": "d", "text": "Monitoring strategy differs by drug."}, {"id": "e", "text": "Both drugs are monitored with same lab."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Warfarin monitoring is INR/PT only, while heparin titration requires frequent aPTT checks every 6 hours.', 'Anticoagulants - NCLEX', true, 97, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "integrated anticoagulant safety" in Anticoagulants? (Select all that apply)', 'The nurse is planning care. Which items apply to "integrated anticoagulant safety" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Escalation sequence is optional."}, {"id": "b", "text": "Antidote readiness is emphasized in NCLEX priorities."}, {"id": "c", "text": "Bleeding signs require immediate action."}, {"id": "d", "text": "Correct lab-drug matching is central to safety."}, {"id": "e", "text": "Anticoagulants do not require routine monitoring."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Safe anticoagulant care requires correct lab-drug pairing, bleeding surveillance, antidote readiness, and structured escalation.', 'Anticoagulants - NCLEX', true, 98, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "aPTT role" in Anticoagulants? (Select all that apply)', 'Which of the following are consistent with "aPTT role" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "Normal aPTT is around 30–40 sec."}, {"id": "b", "text": "aPTT is used to monitor heparin."}, {"id": "c", "text": "Therapeutic heparin aPTT is 45–80 sec."}, {"id": "d", "text": "Therapeutic heparin aPTT is below 20 sec."}, {"id": "e", "text": "aPTT is the primary warfarin monitoring test."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: aPTT monitors heparin therapy; normal is about 30–40 sec and therapeutic heparin range is 45–80 sec.', 'Anticoagulants - NCLEX', true, 99, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "PT/INR role" in Anticoagulants? (Select all that apply)', 'During reassessment, which observations align with "PT/INR role" in Anticoagulants? (Select all that apply)', '[{"id": "a", "text": "PT is associated with warfarin monitoring."}, {"id": "b", "text": "INR goal for most patients is below 1."}, {"id": "c", "text": "INR is used for warfarin monitoring."}, {"id": "d", "text": "Typical therapeutic INR is 2–3."}, {"id": "e", "text": "Warfarin is monitored by aPTT only."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: PT/INR monitor warfarin; INR therapeutic range is 2–3 for most indications.', 'Anticoagulants - NCLEX', true, 100, 1, true);
